  /**
   * calculate_balances
   */
  @Transaction
  public String calculate_balances(Context ctx, String p, String timestamp, String startDate, String endDate, String channelName) {
    ChaincodeStub stub = ctx.getStub();
    ArrayList<String> argss = new ArrayList<>();
    argss.add(p);
    argss.add(timestamp);
    argss.add(startDate);
    argss.add(endDate);
    Chaincode.Response request = null;
    Genson genson = new Genson();
    request = stub.invokeChaincodeWithStringArgs("smc", "get_registered_prosumers", channelName);
    String prosString = request.getStringPayload();
    if (prosString == null) {
      System.out.println("No registered prosumer");
      return null;
    }

    List<ProsumerData> pros = genson.deserialize(prosString, new GenericType<List<ProsumerData>>() {});
    Map<Long, Double> sS = new HashMap<Long, Double>();
    Long ts = 0L;
    Double tnum = 0.0;
    Long startDateN = 0L;
    Long endDateN = 0L;
    Double pN = 0.0;
    pN = Double.valueOf(p);
    ts = Long.valueOf(timestamp);
    startDateN = Long.valueOf(startDate);
    endDateN = Long.valueOf(endDate);
    // 
    String num = "0";
    for (ProsumerData pro : pros) {
      if (startDateN >= Long.valueOf(pro.getTimestampP()) && endDateN <= Long.valueOf(pro.getTimestampP())) {
        pro.setBalancesP(String.valueOf(Double.valueOf(pro.getBalancesP()) + Double.valueOf(pro.getSmi()) * Double.valueOf(pN)));
        pro.setReceived_balance(String.valueOf(Double.valueOf(pro.getSmi()) * Double.valueOf(pN)));
      }
      stub.invokeChaincodeWithStringArgs("prosumer", "transfer", pro.getI_p(), String.valueOf(Double.valueOf(pro.getSmi()) * Double.valueOf(pN)), channelName);
      String OpiString = pro.getOpi_ownership_structure();
      List<EnergyOwnership> Opi = genson.deserialize(OpiString, new GenericType<List<EnergyOwnership>>() {});
      for (EnergyOwnership op : Opi) {
        if (Long.valueOf(op.getTimestamp()) == ts && op.getState().equalsIgnoreCase("match") && Double.valueOf(op.getAmount()) == Double.valueOf(pro.getSmi())) {
          Opi.remove(op);
        }
      }
      String assetSerial = genson.serialize(Opi);
      pro.setOpi_ownership_structure(assetSerial);
    }
    String assetSerialized = genson.serialize(pros);
    stub.invokeChaincodeWithStringArgs("smc", "set_registered_prosumers", assetSerialized, channelName);
    Double pmax = Double.valueOf(stub.getStringState("pmax"));
    request = stub.invokeChaincodeWithStringArgs("smc", "get_registered_consumers", channelName);
    String consString = request.getStringPayload();
    if (consString == null) {
      System.out.println("No registered consumers");
      return null;
    }
    List<ConsumerData> cons = genson.deserialize(consString, new GenericType<List<ConsumerData>>() {});
    for (ConsumerData con : cons) {
      Map<String, String> djt = genson.deserialize(con.getDj_t(), new GenericType<Map<String, String>>() {});
      if (startDateN >= Long.valueOf(con.getTimestampC()) && endDateN <= Long.valueOf(con.getTimestampC())) {
        con.setBalancesC(String.valueOf(Double.valueOf(con.getBalancesC()) + (Double.valueOf(djt.get(ts.toString()))) * Double.valueOf(pmax) - Double.valueOf(con.getDmj()) * Double.valueOf(pN)));
        con.setReceived_balance(String.valueOf((Double.valueOf(djt.get(ts.toString()))) * Double.valueOf(pmax) - Double.valueOf(con.getDmj()) * Double.valueOf(pN)));
      }
      stub.invokeChaincodeWithStringArgs("consumer", "transfer", con.getI_c(), String.valueOf(Double.valueOf(con.getBalancesC()) + (Double.valueOf(djt.get(ts.toString()))) * Double.valueOf(pmax) - Double.valueOf(con.getDmj()) * Double.valueOf(pN)), channelName);
      String OciString = con.getOcj_ownership_structure();
      List<EnergyOwnership> Oci = genson.deserialize(OciString, new GenericType<List<EnergyOwnership>>() {});
      for (EnergyOwnership oc : Oci) {
        if (Long.valueOf(oc.getTimestamp()) == ts && oc.getState().equalsIgnoreCase("match") && Double.valueOf(oc.getAmount()) == Double.valueOf(con.getDmj())) {
          Oci.remove(oc);
        }
      }
      EnergyOwnership ocj = new EnergyOwnership(con.getTxAddrC(), con.getDmj(), "purchased", String.valueOf(ts));
      Oci.add(ocj);
      String assetSerial = genson.serialize(Oci);
      con.setOcj_ownership_structure(assetSerial);
    }
    assetSerialized = genson.serialize(cons);
    stub.invokeChaincodeWithStringArgs("smc", "set_registered_consumers", assetSerialized, channelName);
    return "true";
  }
