  @Transaction
  public String delete(Context ctx, String name, String timestamp, String value, String state, String ij, String channelName) {
    ChaincodeStub stub = ctx.getStub();
    ArrayList<String> argss = new ArrayList<>();
    argss.add(name);
    argss.add(timestamp);
    argss.add(value);
    argss.add(state);
    argss.add(ij);
    Chaincode.Response request = null;
    Long tsN = 0L;
    Double valueN = 0.0;
    String nameN = "";
    String stateN = "";
    Integer ijN = 0;
    Genson genson = new Genson();
    nameN = String.valueOf(name);
    tsN = Long.valueOf(timestamp);
    valueN = Double.valueOf(value);
    stateN = String.valueOf(state);
    ijN = Integer.valueOf(ij);

    if (nameN.equalsIgnoreCase("prosumer")) {
      request = stub.invokeChaincodeWithStringArgs("smc", "get_registered_prosumers", channelName);
      String prosString = request.getStringPayload();
      if (prosString == null) {
        System.out.println("No registered prosumers");
        return null;
      }

      List<ProsumerData> pros = genson.deserialize(prosString, new GenericType<List<ProsumerData>>() {});
      String OpiString = pros.get(ijN).getOpi_ownership_structure();
      List<EnergyOwnership> Opi = genson.deserialize(OpiString, new GenericType<List<EnergyOwnership>>() {});
      for (EnergyOwnership op : Opi) {
        if (Long.valueOf(op.getTimestamp()) == tsN && op.getState().equalsIgnoreCase(stateN) && Double.valueOf(op.getAmount()) == valueN) {
          Opi.remove(op);
        }
      }
      String assetSerial = genson.serialize(Opi);
      pros.get(ijN).setOpi_ownership_structure(assetSerial);
      String assetSerialized = genson.serialize(pros);
      stub.invokeChaincodeWithStringArgs("smc", "set_registered_prosumers", assetSerialized, channelName);
    } else if (nameN.equalsIgnoreCase("consumer")) {
      request = stub.invokeChaincodeWithStringArgs("smc", "get_registered_consumers", channelName);
      String consString = request.getStringPayload();
      if (consString == null) {
        System.out.println("No registered consumers");
        return null;
      }
      List<ConsumerData> cons = genson.deserialize(consString, new GenericType<List<ConsumerData>>() {});
      String OciString = cons.get(ijN).getOcj_ownership_structure();
      List<EnergyOwnership> Oci = genson.deserialize(OciString, new GenericType<List<EnergyOwnership>>() {});
      for (EnergyOwnership oc : Oci) {
        if (Long.valueOf(oc.getTimestamp()) == tsN && oc.getState().equalsIgnoreCase(stateN) && Double.valueOf(oc.getAmount()) == valueN) {
          Oci.remove(oc);
        }
      }
      String assetSerial = genson.serialize(Oci);
      cons.get(ijN).setOcj_ownership_structure(assetSerial);
      String assetSerialized = genson.serialize(cons);
      stub.invokeChaincodeWithStringArgs("smc", "set_registered_consumers", assetSerialized, channelName);
    }
    return "done";
  }

