  public String balances_consumer_set(Context ctx, String num, String i_c, String channelName) {
    // set_balances_consumer
    ChaincodeStub stub = ctx.getStub();
    ArrayList<String> argss = new ArrayList<>();
    argss.add(num);
    argss.add(i_c);
    String numN = "0";
    String i_cN = "0";
    numN = num;
    i_cN = i_c;
    String smcString = stub.getStringState("smc");
    if (smcString == null) {
      System.out.println("No smc");
      return null;
    }
    SmartContractData smc = new Genson().deserialize(smcString, SmartContractData.class);
    ArrayList<Double> balances = new Genson().deserialize(smc.getBalances(), new GenericType<ArrayList<Double>>() {});
    balances.set(Integer.valueOf(i_cN), Double.valueOf(numN) + Double.valueOf(balances.get(Integer.valueOf(i_cN))));
    smc.setBalances(new Genson().serialize(balances));
    stub.putStringState("smc", new Genson().serialize(smc));
    return "true";
  }

  /**
   * validate_prosumer, smc
   */
  @Transaction
  public String validate_prosumer(Context ctx, String startDate, String endDate, String timestamp, String pmax, String Si, String ij, String channelName) {
    ChaincodeStub stub = ctx.getStub();
    ArrayList<String> argss = new ArrayList<>();
    argss.add(startDate);
    argss.add(endDate);
    argss.add(timestamp);
    argss.add(pmax);
    argss.add(Si);
    argss.add(ij);
    Chaincode.Response request = null;
    Long ts = 0L;
    Integer ijN = 0;
    Double SiN = 0.0;
    Long startDateN = 0L;
    Long endDateN = 0L;
    startDateN = Long.valueOf(startDate);
    endDateN = Long.valueOf(endDate);
    ts = Long.valueOf(timestamp);
    ijN = Integer.valueOf(ij);
    boolean flag = false;
    request = stub.invokeChaincodeWithStringArgs("smc", "get_registered_prosumers", channelName);
    String regsString = request.getStringPayload();
    if (regsString == null) {
      System.out.println("No asset");
      return null;
    }
    List<ProsumerData> regs = new Genson().deserialize(regsString, new GenericType<List<ProsumerData>>() {});
    if (Double.valueOf(regs.get(ijN).getEi()) >= Double.valueOf(SiN) && ts >= startDateN && ts <= endDateN) {
      flag = true;
    }
    return String.valueOf(flag);
  }
